import cv2,numpy as np
c=cv2.VideoCapture('example_video.mp4')
i=0;bg=None
while True:
  r,f=c.read()
  if not r:break
  if bg is None: bg=f.astype(int); cv2.imwrite('/tmp/fr/bg.png',f)
  d=np.abs(f.astype(int)-bg).max(2)>40
  ys,xs=np.nonzero(d)
  if len(xs)>200: print(i,len(xs),xs.min(),xs.max(),ys.min(),ys.max())
  else: print(i,len(xs))
  if i%10==0: cv2.imwrite(f'/tmp/fr/{i:03d}.png',f)
  i+=1
"
